fn two_objective_tradeoff(x: &Array1<f64>) -> Vec<f64> {
    vec![x[0] * x[0], (x[0] - 2.0).powi(2)]
}

#[test]
fn nsga2_finds_both_ends_of_simple_front() {
    let report = nsga2(
        &two_objective_tradeoff,
        NsgaConfig {
            bounds: vec![(0.0, 2.0)],
            population_size: 64,
            maxeval: 1_024,
            seed: Some(11),
            ..Default::default()
        },
    )
    .expect("NSGA-II should run");

    assert!(report.pareto_front.len() > 20);
    assert!(
        report.pareto_front.iter().any(|s| s.objectives[0] < 1e-3),
        "front should include the f1 optimum"
    );
    assert!(
        report.pareto_front.iter().any(|s| s.objectives[1] < 1e-3),
        "front should include the f2 optimum"
    );
}

#[test]
fn nsga3_handles_three_objective_front() {
    let f = |x: &Array1<f64>| vec![x[0].powi(2), (x[0] - 1.0).powi(2), (x[0] - 2.0).powi(2)];
    let report = nsga3(
        &f,
        NsgaConfig {
            bounds: vec![(0.0, 2.0)],
            population_size: 72,
            maxeval: 1_200,
            reference_partitions: 8,
            seed: Some(19),
            ..Default::default()
        },
    )
    .expect("NSGA-III should run");

    assert!(report.pareto_front.len() > 10);
    assert!(report.pareto_front.iter().any(|s| s.x[0] < 0.1));
    assert!(report.pareto_front.iter().any(|s| s.x[0] > 1.9));
}

#[test]
fn dominance_requires_strict_improvement() {
    assert!(dominates(&[1.0, 2.0], &[1.0, 3.0]));
    assert!(!dominates(&[1.0, 2.0], &[1.0, 2.0]));
    assert!(!dominates(&[2.0, 1.0], &[1.0, 2.0]));
}

#[test]
fn test_perpendicular_distance_basic() {
    // Point lies on the reference direction -> distance is 0.
    assert!(perpendicular_distance(&[2.0, 0.0], &[1.0, 0.0]).abs() < 1e-12);

    // Zero-reference falls back to Euclidean norm.
    assert!((perpendicular_distance(&[3.0, 4.0], &[0.0, 0.0]) - 5.0).abs() < 1e-12);
}

#[test]
fn test_nearest_reference() {
    let refs = vec![vec![1.0, 0.0], vec![0.0, 1.0]];
    let (idx, _) = nearest_reference(&[0.9, 0.1], &refs);
    assert_eq!(idx, 0);
    let (idx, _) = nearest_reference(&[0.1, 0.9], &refs);
    assert_eq!(idx, 1);
}

#[test]
fn test_normalise_objectives() {
    let obj = vec![1.0, 2.0];
    let ideal = vec![0.0, 1.0];
    let nadir = vec![2.0, 3.0];
    let n = normalise_objectives(&obj, &ideal, &nadir);
    assert!((n[0] - 0.5).abs() < 1e-12);
    assert!((n[1] - 0.5).abs() < 1e-12);

    // Zero span should not panic and maps to 0.
    let n2 = normalise_objectives(&[5.0], &[5.0], &[5.0]);
    assert_eq!(n2[0], 0.0);
}

#[test]
fn test_default_reference_partitions() {
    assert_eq!(default_reference_partitions(0), 1);
    assert_eq!(default_reference_partitions(1), 1);
    assert_eq!(default_reference_partitions(2), 24);
    assert_eq!(default_reference_partitions(5), 3);
}

#[test]
fn test_sum_objectives() {
    assert_eq!(sum_objectives(&[1.0, 2.0, 3.0]), 6.0);
}

#[test]
fn test_clamp_to_bounds() {
    let x = Array1::from_vec(vec![-1.0, 5.0, 0.5]);
    let c = clamp_to_bounds(x, &[(0.0, 1.0), (0.0, 1.0), (0.0, 1.0)]);
    assert_eq!(c.to_vec(), vec![0.0, 1.0, 0.5]);
}

#[test]
fn test_random_in_bounds_respects_limits() {
    let mut rng = StdRng::seed_from_u64(1);
    let x = random_in_bounds(&[(0.0, 1.0), (-2.0, -1.0)], &mut rng);
    assert!(x[0] >= 0.0 && x[0] <= 1.0);
    assert!(x[1] >= -2.0 && x[1] <= -1.0);
}
